<?php
declare(strict_types=1);
function financeTeamTransaction(PDO $pdo):void{$pdo->beginTransaction();if(!$pdo->query('SELECT id FROM finance_team_mutex WHERE id=1 FOR UPDATE')->fetchColumn()){$pdo->rollBack();throw new RuntimeException('Controle financeiro indisponivel.');}}
function financeTeamAccounts(PDO $pdo):array{return array_merge([['id'=>0,'name'=>'Caixa geral']],$pdo->query('SELECT id,name FROM finance_team_accounts ORDER BY name')->fetchAll(PDO::FETCH_ASSOC));}
function financeTeamAccountValid(PDO $pdo,int $id):void{if($id<0)throw new DomainException('Conta invalida.');if($id){$s=$pdo->prepare('SELECT id FROM finance_team_accounts WHERE id=?');$s->execute([$id]);if(!$s->fetchColumn())throw new DomainException('Conta nao encontrada.');}}
function financeTeamReason(string $reason):string{$reason=trim($reason);if($reason===''||mb_strlen($reason)>500)throw new DomainException('Informe o motivo, com ate 500 caracteres.');return $reason;}
function financeTeamSignedCents(string $value):int{if(!preg_match('/^(-?)(\d{1,15})(?:\.(\d{1,2}))?$/D',$value,$m))throw new DomainException('Valor invalido.');return ($m[1]==='-'?-1:1)*((int)$m[2]*100+(int)str_pad($m[3]??'',2,'0'));}
function financeTeamAccountDate(PDO $pdo,int $id,string $date):void{$s=$pdo->prepare('SELECT balance_date FROM finance_team_openings WHERE account_id=?');$s->execute([$id]);$opening=$s->fetchColumn();if($opening&&$date<$opening)throw new DomainException('Data anterior ao saldo inicial desta conta.');}
function financeTeamAccountBalance(PDO $pdo,int $id):int{
 financeTeamAccountValid($pdo,$id);$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN e.type='income' THEN e.amount ELSE -e.amount END),0) FROM finance_entries e LEFT JOIN finance_team_account_entries a ON a.entry_id=e.id WHERE e.status='paid' AND COALESCE(a.account_id,0)=? AND COALESCE(e.source,'manual') NOT IN ('balance_deposit','balance_usage')");$s->execute([$id]);$total=financeTeamSignedCents((string)$s->fetchColumn());
 $s=$pdo->prepare('SELECT amount FROM finance_team_openings WHERE account_id=?');$s->execute([$id]);$value=$s->fetchColumn();if($value!==false)$total+=financeTeamSignedCents((string)$value);
 $s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN to_account_id=? THEN amount ELSE -amount END),0) FROM finance_team_transfers WHERE status='active' AND (from_account_id=? OR to_account_id=?)");$s->execute([$id,$id,$id]);return $total+financeTeamSignedCents((string)$s->fetchColumn());
}
function financeTeamOpeningTotal(PDO $pdo):float{return (float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM finance_team_openings')->fetchColumn();}
function financeTeamAssignAccount(PDO $pdo,array $entry,int $accountId):void{
 financeTeamAccountValid($pdo,$accountId);$s=$pdo->prepare('SELECT balance_date FROM finance_team_openings WHERE account_id=?');$s->execute([$accountId]);$date=$s->fetchColumn();if($date&&$entry['paid_at']<$date)throw new DomainException('Data anterior ao saldo inicial desta conta.');
 $pdo->prepare('INSERT IGNORE INTO finance_team_account_entries(entry_id,account_id) VALUES(?,?)')->execute([$entry['id'],$accountId]);
}
function financeTeamTreasuryAudit(PDO $pdo,string $action,int $actor,string $reason,?array $before,array $after):void{if(!$pdo->inTransaction())throw new LogicException('Transacao obrigatoria.');$pdo->prepare('INSERT INTO finance_team_treasury_history(action,actor_user_id,reason,before_json,after_json) VALUES(?,?,?,?,?)')->execute([$action,$actor,$reason,$before?json_encode($before,JSON_THROW_ON_ERROR):null,json_encode($after,JSON_THROW_ON_ERROR)]);}
function financeTeamTreasury(PDO $pdo,array $input,int $actor):void{
 if($actor<=0)throw new DomainException('Responsavel invalido.');$action=$input['action']??'';financeTeamTransaction($pdo);
 try{
  if($action==='account'){$name=trim((string)($input['name']??''));if($name===''||mb_strlen($name)>120)throw new DomainException('Informe o nome da conta.');$pdo->prepare('INSERT INTO finance_team_accounts(name,created_by_user_id) VALUES(?,?)')->execute([$name,$actor]);financeTeamTreasuryAudit($pdo,'account_created',$actor,'Cadastro da conta',null,['name'=>$name]);}
  elseif($action==='opening'){$id=(int)($input['account_id']??-1);financeTeamAccountValid($pdo,$id);$reason=financeTeamReason((string)($input['reason']??''));$raw=(string)($input['amount']??'');if(!preg_match('/^-?\d{1,10}(?:\.\d{1,2})?$/D',$raw))throw new DomainException('Valor invalido.');$amount=financeTeamSignedCents($raw);$date=(string)($input['movement_date']??'');if(!financeTeamDate($date))throw new DomainException('Data invalida.');$s=$pdo->prepare('SELECT * FROM finance_team_openings WHERE account_id=?');$s->execute([$id]);$before=$s->fetch(PDO::FETCH_ASSOC)?:null;
   $s=$pdo->prepare("SELECT COUNT(*) FROM finance_entries e LEFT JOIN finance_team_account_entries a ON a.entry_id=e.id WHERE COALESCE(a.account_id,0)=? AND e.status='paid' AND e.paid_at<?");$s->execute([$id,$date]);if((int)$s->fetchColumn())throw new DomainException('Ja existem movimentos anteriores a esta data.');
   $s=$pdo->prepare('SELECT COUNT(*) FROM finance_team_transfers WHERE (from_account_id=? OR to_account_id=?) AND movement_date<?');$s->execute([$id,$id,$date]);if((int)$s->fetchColumn())throw new DomainException('Ja existem transferencias anteriores a esta data.');$value=($amount<0?'-':'').financeTeamDecimal(abs($amount));$pdo->prepare('INSERT INTO finance_team_openings(account_id,amount,balance_date,reason,actor_user_id) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount),balance_date=VALUES(balance_date),reason=VALUES(reason),actor_user_id=VALUES(actor_user_id)')->execute([$id,$value,$date,$reason,$actor]);financeTeamTreasuryAudit($pdo,'opening_set',$actor,$reason,$before,['account_id'=>$id,'amount'=>$value,'balance_date'=>$date]);
  }elseif($action==='transfer'){$from=(int)($input['from_account_id']??-1);$to=(int)($input['to_account_id']??-1);financeTeamAccountValid($pdo,$from);financeTeamAccountValid($pdo,$to);if($from===$to)throw new DomainException('Escolha contas diferentes.');$amount=financeTeamCents((string)($input['amount']??''));if($amount<=0)throw new DomainException('Valor invalido.');$date=(string)($input['movement_date']??'');if(!financeTeamDate($date))throw new DomainException('Data invalida.');$reason=financeTeamReason((string)($input['reason']??''));$key=(string)($input['request_key']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('Reabra o formulario.');$fp=hash('sha256',json_encode([$from,$to,$amount,$date,$reason,$actor]));$s=$pdo->prepare('SELECT fingerprint FROM finance_team_transfers WHERE request_key=?');$s->execute([$key]);$old=$s->fetchColumn();if($old){if(!hash_equals($old,$fp))throw new DomainException('Envio ja utilizado.');$pdo->commit();return;}
   financeTeamAccountDate($pdo,$from,$date);financeTeamAccountDate($pdo,$to,$date);if(financeTeamAccountBalance($pdo,$from)<$amount)throw new DomainException('Saldo insuficiente na origem.');$pdo->prepare('INSERT INTO finance_team_transfers(from_account_id,to_account_id,amount,movement_date,reason,actor_user_id,request_key,fingerprint) VALUES(?,?,?,?,?,?,?,?)')->execute([$from,$to,financeTeamDecimal($amount),$date,$reason,$actor,$key,$fp]);financeTeamTreasuryAudit($pdo,'transfer_created',$actor,$reason,null,['id'=>(int)$pdo->lastInsertId(),'from'=>$from,'to'=>$to,'amount'=>financeTeamDecimal($amount)]);
  }elseif($action==='cancel_transfer'){$s=$pdo->prepare('SELECT * FROM finance_team_transfers WHERE id=?');$s->execute([(int)($input['id']??0)]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new DomainException('Transferencia nao encontrada.');$reason=financeTeamReason((string)($input['reason']??''));if($row['status']==='active'){if(financeTeamAccountBalance($pdo,(int)$row['to_account_id'])<financeTeamCents($row['amount']))throw new DomainException('O destino ja utilizou o saldo. Regularize antes de cancelar.');$pdo->prepare("UPDATE finance_team_transfers SET status='canceled' WHERE id=?")->execute([$row['id']]);financeTeamTreasuryAudit($pdo,'transfer_canceled',$actor,$reason,$row,['status'=>'canceled']);}}
  else throw new DomainException('Acao invalida.');$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
